/*\ TaxiTracker message handler v6 \*/
exports.name = 'taxitracker-messages';
exports.after = ['taxitracker-startup'];
exports.platforms = ['browser'];
exports.synchronous = true;

exports.startup = function() {

  function tw(key) {
    return ($tw.wiki.getTiddlerText('$:/taxitracker/'+key,'')||'').trim();
  }
  function setTw(key,val) {
    $tw.wiki.addTiddler(new $tw.Tiddler({title:'$:/taxitracker/'+key, text:String(val||'')}));
  }
  function notify(msg, isErr) {
    $tw.wiki.addTiddler(new $tw.Tiddler({
      title: '$:/taxitracker/state/last-message',
      text:  msg,
      error: isErr ? 'yes' : 'no'
    }));
  }

  function waitForApi(cb) {
    if (window.TaxiTracker) { cb(); }
    else { setTimeout(function(){ waitForApi(cb); }, 100); }
  }

  waitForApi(function() {
    var TT = window.TaxiTracker;

    setTw('scratch/txn-time', TT.nowTime());
    setInterval(function(){ setTw('scratch/txn-time', TT.nowTime()); }, 30000);

    function updateShiftTotals() {
      var s = TT.calcSummary();
      setTw('state/shift-cash',   TT.fmt(s.cash));
      setTw('state/shift-card',   TT.fmt(s.card));
      setTw('state/shift-acct',   TT.fmt(s.acct));
      setTw('state/shift-driver', TT.fmt(s.driver));
    }

    function showConfirm(msg, action) {
      setTw('state/confirm-msg', msg);
      setTw('state/confirm-action', action);
    }

    function performSaveShift(validType) {
      var time = TT.nowTime();
      var car  = tw('scratch/shift-car');
      var r1 = tw('scratch/shift-r1'), r2 = tw('scratch/shift-r2');
      var r3 = tw('scratch/shift-r3'), r4 = tw('scratch/shift-r4');
      var r = TT.saveShift(validType, time, car, r1, r2, r3, r4);
      notify(r.ok ? validType + ' saved ✓' : r.msg, !r.ok);
    }

    document.addEventListener('focusin', function(e) {
      if (e.target.matches('.tt-meter-input,.tt-money-input,.tt-split-amount,.tt-r-input,.tt-notes-input')) {
        e.target.select();
      }
    });

    TT.journalReconcile();
    updateShiftTotals();

    $tw.rootWidget.addEventListener('tt-record-txn', function() {
      var editingTxn = tw('state/editing-txn');
      if (editingTxn) {
        setTw('scratch/txn-time', TT.nowTime());
        var r = TT.updateTxn(editingTxn);
        setTw('state/editing-txn', '');
        ['meter','charge','cashin','fees','notes'].forEach(function(k) {
          setTw('state/edit-orig-' + k, '');
          setTw('state/edit-dirty-' + k, '');
        });
        notify(r.ok ? 'Transaction updated ✓' : r.msg, !r.ok);
        if (r.ok) updateShiftTotals();
        return;
      }
      setTw('scratch/txn-time', TT.nowTime());
      var notesVal = tw('scratch/notes').trim();
      if (!notesVal.toUpperCase().startsWith('FD ') && /^\w+\s+\w+\s+\d{2}$/.test(notesVal)) {
        setTw('scratch/payment', 'Card');
      }
      var payment = tw('scratch/payment');
      var splitMode = tw('scratch/split-mode');
      var splitGroup = tw('state/split-group');
      if (!payment && splitMode !== 'yes' && !splitGroup) {
        setTw('state/payment-popup', 'open');
        return;
      }
      var r = TT.recordTxn();
      if (r.ok) {
        updateShiftTotals();
        if (r.splitRemaining !== undefined) {
          notify(r.splitRemaining > 0
            ? 'Leg recorded ✓ — £' + r.splitRemaining.toFixed(2) + ' remaining'
            : 'Split complete ✓', false);
        } else {
          notify('Recorded ✓', false);
        }
      } else {
        notify(r.msg, true);
      }
    });

    $tw.rootWidget.addEventListener('tt-popup-select-and-record', function() {
      setTw('scratch/txn-time', TT.nowTime());
      var r = TT.recordTxn();
      setTw('state/payment-popup', '');
      if (r.ok) updateShiftTotals();
      notify(r.ok ? 'Recorded ✓' : r.msg, !r.ok);
    });

    $tw.rootWidget.addEventListener('tt-save-shift', function() {
      var type = tw('scratch/shift-type');
      if (!type) { notify('Select Start or End first', true); return; }
      var validType = type.charAt(0).toUpperCase() + type.slice(1).toLowerCase();
      if (validType !== 'Start' && validType !== 'End') { notify('Type must be Start or End', true); return; }
      var existing = TT.getShift(validType);
      if (existing) {
        showConfirm('Shift ' + validType + ' already saved (' + existing['shift-time'] + '). Overwrite?', 'save-shift');
        return;
      }
      performSaveShift(validType);
    });

    $tw.rootWidget.addEventListener('tt-cancel-split', function() {
      ['state/split-group','state/split-leg-count','state/split-remaining',
       'state/split-total','state/split-allocated','scratch/split-mode'].forEach(function(k) {
        setTw(k, '');
      });
      notify('Split cancelled', false);
    });

    $tw.rootWidget.addEventListener('tt-end-shift', function() {
      var shiftDate = TT.getActiveShiftDate ? TT.getActiveShiftDate() : '';
      var existing = shiftDate && $tw.wiki.getTiddler('Daily Sheet ' + shiftDate);
      if (existing) {
        showConfirm('Daily sheet already generated. Regenerate and resend?', 'end-shift');
      } else {
        showConfirm('Generate daily sheet, send to Telegram and download backup?', 'end-shift');
      }
    });

    $tw.rootWidget.addEventListener('tt-close-shift', function() {
      var shiftDate = TT.getActiveShiftDate ? TT.getActiveShiftDate() : '';
      var hasSheet = shiftDate && $tw.wiki.getTiddler('Daily Sheet ' + shiftDate);
      if (!hasSheet) {
        showConfirm('Daily sheet not yet generated — data has not been sent. Close shift anyway?', 'close-shift');
      } else {
        showConfirm('Close shift and reset for next shift? All transaction data is kept.', 'close-shift');
      }
    });

    $tw.rootWidget.addEventListener('tt-edit-txn', function(event) {
      var title = event.paramObject && event.paramObject.txnTitle;
      if (!title) return;
      var t = $tw.wiki.getTiddler(title);
      if (!t) { notify('Transaction not found', true); return; }
      var f = t.fields;
      TT.clearScratch();
      var meterPence = String(Math.round((parseFloat(f.meter)||0) * 100));
      var isSplit = f.split === 'yes';
      setTw('scratch/payment',   isSplit ? '' : (f.payment || ''));
      setTw('scratch/meter',     meterPence);
      setTw('scratch/charge',    f.charge   || '');
      setTw('scratch/cashin',    f.cashin   || '');
      setTw('scratch/overring',  f.overring || '');
      setTw('scratch/gratuity',  f.gratuity || '');
      setTw('scratch/fees',      f.fees     || '');
      setTw('scratch/notes',     f.notes    || '');
      setTw('scratch/txn-time',  f['txn-time'] || '');
      setTw('scratch/split-mode', isSplit ? 'yes' : '');
      if (isSplit) {
        setTw('scratch/split-1-type',   f['split-1-type']   || '');
        setTw('scratch/split-1-amount', f['split-1-amount'] || '');
        setTw('scratch/split-2-type',   f['split-2-type']   || '');
        setTw('scratch/split-2-amount', f['split-2-amount'] || '');
        setTw('scratch/split-3-type',   f['split-3-type']   || '');
        setTw('scratch/split-3-amount', f['split-3-amount'] || '');
      }
      setTw('state/edit-orig-meter',  meterPence);
      setTw('state/edit-orig-charge', f.charge  || '');
      setTw('state/edit-orig-cashin', f.cashin  || '');
      setTw('state/edit-orig-fees',   f.fees    || '');
      setTw('state/edit-orig-notes',  f.notes   || '');
      ['meter','charge','cashin','fees','notes'].forEach(function(k) {
        setTw('state/edit-dirty-' + k, '0');
      });
      setTw('state/editing-txn', title);
    });

    $tw.rootWidget.addEventListener('tt-cancel-edit', function() {
      TT.clearScratch();
      setTw('state/editing-txn', '');
      ['meter','charge','cashin','fees','notes'].forEach(function(k) {
        setTw('state/edit-orig-' + k, '');
        setTw('state/edit-dirty-' + k, '');
      });
    });

    $tw.rootWidget.addEventListener('tt-confirm-proceed', function() {
      var action = tw('state/confirm-action');
      setTw('state/confirm-action', '');
      setTw('state/confirm-msg', '');
      if (action === 'save-shift') {
        var type = tw('scratch/shift-type');
        var validType = type.charAt(0).toUpperCase() + type.slice(1).toLowerCase();
        performSaveShift(validType);
      } else if (action === 'end-shift') {
        var r = TT.endShift();
        notify(r.ok ? 'Daily sheet sent ✓' : r.msg, !r.ok);
      } else if (action === 'close-shift') {
        TT.closeShift();
        notify('Shift closed ✓', false);
      }
    });

    $tw.rootWidget.addEventListener('tt-freeze-invoice', function() {
      var weekNum = parseInt(($tw.wiki.getTiddlerText('$:/taxitracker/active-week','')||'').trim(), 10);
      var weekYr  = TT.isoWeekYear();
      if (!weekNum || weekNum < 1 || weekNum > 53) { notify('Enter a valid week number (1-53)', true); return; }
      var r = TT.freezeInvoice(weekNum, weekYr);
      notify(r.ok ? 'Frozen as: ' + r.title : r.msg, !r.ok);
    });

    $tw.rootWidget.addEventListener('tt-paste-import', function() {
      var raw = ($tw.wiki.getTiddlerText('$:/taxitracker/scratch/recover-paste','')||'').trim();
      if(!raw) { notify('Paste a CHECKPOINT or ENDSHIFT message first', true); return; }
      var json;
      try {
        var s = raw.replace(/^(CHECKPOINT|ENDSHIFT)::/,'');
        json = JSON.parse(s);
      } catch(e) { notify('Invalid JSON — paste the full message from Telegram', true); return; }
      var txns = json.transactions || [];
      var imported = 0;
      txns.forEach(function(f){
        if(!f.title) return;
        if(!$tw.wiki.getTiddler(f.title)){
          $tw.wiki.addTiddler(new $tw.Tiddler($tw.wiki.getCreationFields(), f));
          imported++;
        }
      });
      if(imported > 0) $tw.rootWidget.dispatchEvent({type:'tm-auto-save-wiki'});
      TT.journalReconcile();
      if (imported > 0) updateShiftTotals();
      notify(imported > 0 ? 'Imported '+imported+' transaction(s) ✓' : 'All transactions already present', false);
    });

    $tw.rootWidget.addEventListener('tt-recover-journal', function() {
      var raw = $tw.wiki.getTiddlerText('$:/taxitracker/state/journal-orphans','[]');
      var missing; try{ missing=JSON.parse(raw); } catch(e){ missing=[]; }
      var imported = 0;
      missing.forEach(function(f){
        if(f.title && !$tw.wiki.getTiddler(f.title)){
          $tw.wiki.addTiddler(new $tw.Tiddler($tw.wiki.getCreationFields(), f));
          imported++;
        }
      });
      if(imported > 0) $tw.rootWidget.dispatchEvent({type:'tm-auto-save-wiki'});
      TT.journalReconcile();
      if (imported > 0) updateShiftTotals();
      notify(imported > 0 ? 'Restored '+imported+' transaction(s) ✓' : 'Nothing to restore', false);
    });

    $tw.rootWidget.addEventListener('tt-download-backup', function() {
      var d = TT.getActiveShiftDate() || TT.todayPrefix();
      TT.downloadBackup(d);
    });

    var meterWatching = false;
    $tw.wiki.addEventListener('change', function(changes) {

      if (changes['$:/taxitracker/scratch/meter'] && !meterWatching) {
        meterWatching = true;
        try {
          var raw = tw('scratch/meter');
          if (!raw || !/^\d+$/.test(raw)) {
            ['charge','overring','cashin','gratuity'].forEach(function(f){
              setTw('scratch/'+f, '');
            });
            setTw('state/meter-display', '');
          } else {
            var pence   = parseInt(raw, 10);
            var pounds  = pence / 100;
            var charge  = Math.floor(pounds * 10) / 10;
            var overring = parseFloat((pounds - charge).toFixed(2));
            setTw('state/meter-display', pounds.toFixed(2));
            setTw('scratch/charge',   charge.toFixed(2));
            setTw('scratch/overring', overring.toFixed(2));
            setTw('scratch/cashin',   charge.toFixed(2));
            setTw('scratch/gratuity', '0.00');
          }
        } finally {
          meterWatching = false;
        }
      }

      if (!meterWatching &&
          (changes['$:/taxitracker/scratch/cashin'] || changes['$:/taxitracker/scratch/charge'])) {
        var chargeVal  = parseFloat(tw('scratch/charge'))  || 0;
        var cashinVal  = parseFloat(tw('scratch/cashin'))  || 0;
        var meterPence = parseInt(tw('scratch/meter'), 10) || 0;
        var meterPounds = meterPence / 100;
        if (chargeVal > 0) {
          setTw('scratch/gratuity', (cashinVal - chargeVal).toFixed(2));
          setTw('scratch/overring', (meterPounds - chargeVal).toFixed(2));
        }
      }

      if (changes['$:/taxitracker/scratch/notes']) {
        var notesVal = tw('scratch/notes').trim();
        if (/^\w+\s+\w+\s+\d{2}$/.test(notesVal)) {
          setTw('scratch/payment', 'Card');
        }
      }

            if (tw('state/editing-txn')) {
        ['meter','charge','cashin','fees','notes'].forEach(function(k) {
          if (changes['$:/taxitracker/scratch/' + k]) {
            var cur = tw('scratch/' + k);
            var orig = tw('state/edit-orig-' + k);
            setTw('state/edit-dirty-' + k, cur !== orig ? '1' : '0');
          }
        });
      }

    });

  }); // end waitForApi

}; // end exports.startup

