.tt-meter-label { font-size:0.85em; color:#aaa; margin-bottom:4px; }
.tt-meter-input {
  font-size:1.8em; padding:8px; width:160px;
  font-family:monospace; text-align:right; display:block; margin-bottom:4px;
}
.tt-meter-pounds { font-size:1.4em; font-family:monospace; font-weight:bold; color:#4caf50; }
.tt-money-input { font-size:1.1em; padding:6px; width:100px; font-family:monospace; text-align:right; }
.tt-notes-input { width:100%; max-width:400px; padding:6px; font-size:1em; }
.tt-time-input { font-size:1.2em; padding:8px; }
.tt-car-input { font-size:1.1em; padding:6px; width:120px; }
.tt-r-input { font-size:1.1em; padding:6px; width:90px; font-family:monospace; text-align:right; }
.tt-week-input { font-size:1.3em; padding:6px; width:80px; margin-left:8px; font-family:monospace; text-align:right; }
.tt-muted-row { color:#666; font-family:monospace; font-size:0.95em; margin:4px 0 8px; }
.tt-confirm-row {
  background:#e8f5e9; border-left:2px solid #4caf50;
  padding:8px 12px; margin:8px 0; font-family:monospace;
  color:#1b5e20; border-radius:3px;
}
.tt-last-msg { min-height:1.5em; padding:4px 0; color:#aaa; font-size:0.9em; }
.tt-txn-row { padding:8px 0; border-bottom:1px solid #2a2a2a; line-height:1.6; }
.tt-txn-time { font-family:monospace; font-size:0.85em; color:#666; margin-right:8px; }
.tt-txn-type { font-weight:bold; margin-right:6px; }
.tt-txn-charge { font-family:monospace; font-weight:bold; }
.tt-txn-tip { color:#4caf50; font-family:monospace; }
.tt-txn-fees { color:#e6a817; font-family:monospace; margin-left:6px; }
.tt-txn-notes { color:#888; font-style:italic; margin-left:6px; }
.tt-txn-split { color:#aaa; font-size:0.85em; margin-right:4px; }
.tt-inv-table { width:100%; border-collapse:collapse; margin:8px 0; }
.tt-inv-table th { text-align:left; padding:6px 4px; border-bottom:2px solid #444; }
.tt-inv-row td { padding:6px 4px; border-bottom:1px solid #2a2a2a; }
.tt-inv-num { text-align:right; font-family:monospace; }
.tt-inv-total td { padding:8px 4px; border-top:2px solid #444; font-weight:bold; }
.tt-split-section { margin:8px 0; }
.tt-split-row { display:flex; gap:6px; align-items:center; margin:6px 0; }
.tt-split-pills { display:flex; gap:4px; flex-shrink:0; }
.tt-split-pill { padding:6px 10px; border-radius:4px; cursor:pointer; font-size:0.9em; font-weight:600; border:2px solid transparent; }
.tt-split-amount { font-size:1.1em; padding:6px; width:90px; font-family:monospace; text-align:right; flex:1; }
.tt-split-remaining { font-family:monospace; font-size:0.9em; color:#aaa; margin-top:6px; padding:4px 0; border-top:1px solid #2a2a2a; }
.tt-split-toggle { padding:8px 16px; border-radius:4px; border:2px solid #ffe082; background:#fff8e1; color:#e65100; cursor:pointer; margin-left:6px; font-weight:600; }
.tt-split-toggle.tt-sel { border-color:#e6a817; color:#7a4100; background:#fff3cd; }
.tt-add-split-btn { padding:6px 14px; border:1px solid #ccc; background:#f5f5f5; color:#333; border-radius:4px; cursor:pointer; font-size:0.9em; margin-top:4px; }
.tt-remove-split-btn { padding:4px 8px; border:1px solid #ccc; background:#f5f5f5; color:#555; border-radius:4px; cursor:pointer; font-size:0.85em; flex-shrink:0; }
.tt-backup-btn { padding:5px 10px; border:1px solid #ddd; background:#f5f5f5; color:#333; font-size:0.8em; border-radius:4px; cursor:pointer; margin-left:8px; }
.tt-recovery-banner { background:#fff8e1; border-left:3px solid #e6a817; padding:8px 12px; margin:8px 0; color:#7a4100; border-radius:3px; font-size:0.95em; }
.tt-recover-textarea { width:100%; min-height:100px; font-family:monospace; font-size:0.85em; padding:8px; box-sizing:border-box; }
.tt-check-row { display:flex; align-items:flex-start; gap:10px; padding:10px 12px; margin:6px 0; border-radius:4px; border-left:4px solid #ccc; background:#f5f5f5; color:#000; line-height:1.5; }
.tt-check-ok  { border-color:#4caf50; background:#e8f5e9; }
.tt-check-warn { border-color:#e6a817; background:#fffde7; }
.tt-check-icon { font-size:1.1em; flex-shrink:0; width:1.4em; text-align:center; margin-top:2px; }
/* v6.1 additions */
.tt-shift-note { font-size:0.85em; color:#000; margin-top:3px; padding-left:2px; }
.tt-checklist-action-btn {
  background:#fff9c4; color:#000; border:1px solid #f9a825;
  padding:6px 14px; border-radius:4px; cursor:pointer; margin-top:6px; display:inline-block;
}
/* v6.2 additions */
.tt-ride-time-row { display:flex; align-items:center; gap:10px; margin:4px 0 10px; }
.tt-ride-time-label { color:#666; font-size:0.9em; }
.tt-ride-time-value { font-family:monospace; font-size:1.4em; font-weight:bold; color:#1b5e20; }
.tt-popup-overlay {
  position:fixed; top:0; left:0; right:0; bottom:0;
  background:rgba(0,0,0,0.55); z-index:9999;
  display:flex; align-items:center; justify-content:center;
}
.tt-popup {
  background:#fff; border-radius:10px; padding:24px 20px;
  min-width:260px; max-width:90vw;
  box-shadow:0 6px 24px rgba(0,0,0,0.3);
}
.tt-popup-title {
  font-size:1.05em; font-weight:bold; color:#333;
  text-align:center; margin-bottom:16px;
}
.tt-popup-btn {
  display:block; width:100%; padding:14px 0; margin:8px 0;
  text-align:center; border-radius:6px;
  font-size:1.1em; font-weight:bold; cursor:pointer;
  border:2px solid transparent;
}
.tt-popup-cash    { background:#e8f5e9; color:#1b5e20; border-color:#a5d6a7; }
.tt-popup-card    { background:#e3effa; color:#0d3a6e; border-color:#90bbde; }
.tt-popup-account { background:#fce8e8; color:#7a1010; border-color:#e9a0a0; }
.tt-popup-cancel  {
  display:block; width:100%; padding:8px 0; margin-top:12px;
  background:none; border:none; color:#999; font-size:0.9em; cursor:pointer; text-align:center;
}
.tt-totals-grid { margin:8px 0; }
.tt-total-row {
  display:flex; justify-content:space-between; align-items:center;
  padding:10px 14px; margin:5px 0; border-radius:4px; border-left:4px solid #ccc;
}
.tt-total-cash   { border-color:#4caf50; background:#e8f5e9; }
.tt-total-card   { border-color:#90bbde; background:#e3effa; }
.tt-total-acct   { border-color:#e9a0a0; background:#fce8e8; }
.tt-total-driver { border-color:#ffe082; background:#fff8e1; }
.tt-total-label  { font-weight:bold; color:#333; font-size:0.95em; }
.tt-total-value  { font-family:monospace; font-size:1.15em; font-weight:bold; color:#111; }
.tt-split-hint { font-size:0.85em; color:#666; font-style:italic; margin-bottom:10px; }
.tt-split-row-label { font-size:0.78em; color:#888; text-transform:uppercase; letter-spacing:0.05em; margin:8px 0 2px; }
.tt-split-balance { padding:7px 12px; border-radius:4px; font-family:monospace; font-size:0.95em; margin-top:8px; font-weight:bold; }
.tt-split-bal-ok   { background:#e8f5e9; color:#1b5e20; border:1px solid #a5d6a7; }
.tt-split-bal-warn { background:#fff8e1; color:#e65100; border:1px solid #ffe082; }
.tt-shift-field-row { display:flex; align-items:center; gap:8px; margin:6px 0; }
.tt-shift-field-label { font-size:0.9em; min-width:28px; }
.tt-val-prefill { color: #aaa; }
.tt-edit-banner {
  background:#fff8e1; border-left:4px solid #ffc107;
  padding:8px 12px; margin:6px 0;
  display:flex; justify-content:space-between; align-items:center;
  font-weight:bold; color:#e65100; border-radius:0 4px 4px 0;
}
.tt-cancel-edit-btn {
  background:none; border:1px solid #e65100; color:#e65100;
  padding:4px 10px; border-radius:4px; font-size:0.9em; cursor:pointer;
}
.tt-edit-txn-btn {
  background:none; border:1px solid #bbb; color:#555;
  border-radius:4px; padding:1px 7px; font-size:0.8em;
  margin-left:6px; cursor:pointer;
}
/* v6.5 split redesign */
.tt-split-progress { background:#fff8e1; border-left:3px solid #e6a817; padding:8px 12px; margin:8px 0; border-radius:0 4px 4px 0; }
.tt-split-progress-title { font-weight:bold; color:#e65100; margin-bottom:6px; font-size:0.95em; }
.tt-split-leg-row { font-family:monospace; font-size:0.9em; color:#555; padding:3px 0; border-bottom:1px solid #f0e0b0; }
.tt-split-remaining-label { font-size:1.05em; font-weight:bold; font-family:monospace; color:#e65100; margin-top:6px; }
.tt-cancel-split-btn { margin-top:6px; padding:4px 12px; background:none; border:1px solid #e65100; color:#e65100; border-radius:4px; cursor:pointer; font-size:0.85em; }
.tt-split-status { color:#e65100; font-weight:bold; }
.tt-txn-split { color:#e65100; font-size:0.8em; font-weight:bold; margin-right:4px; }
.tt-txn-split-link { font-size:0.78em; color:#888; margin-left:4px; }
